관리툴function showCrop() {   //$('#glassAnimals').modal({   //backdrop: 'static'	   //});}//파일 바이트 체크 221112$(document).ready(function(){   //크롭추가   //$(".ck-toolbar__items").append('<div style="float:right;width:50px;border:#000000 0px solid;position:relative;top:1px;left:4px;"><img src="http://www.weschoolnews.kr/modules/news/themes/_pc/default/image/crop.png" style="cursor:pointer;" title="이미지 크롭" onclick="showCrop();"></div>');	$('.ck-powered-by').remove();   //단어수 숨김   $(".ck-word-count__words").addClass("hide");	$('#deleteForm').ajaxForm({		beforeSend: function() {					},				complete: function(xhr) {			try {				var res = jQuery.parseJSON(xhr.responseText);				if( res.code > 0 ) {					if( $('#upload-list ul #' + res.upid) )						$('#upload-list ul #' + res.upid).remove();											if( !$('#upload-list ul').children().length )						$('#upload-clear').hide();										// upfiles 로부터 upid 제거					var upfiles = $('#upfilesValue').val();					upfiles = upfiles.replace('[' + res.upid + ']', '');					$('#upfilesValue').val(upfiles);														// 결과 메시지 출력					var msg = '[' + res.name + '] 파일이 삭제되었습니다.';					if( res.type == 2 )						msg += '\n이미지 파일의 경우, 에디터에서 직접 HTML 코드를 제거해 주셔야 합니다.';					alert(msg);				}				if( res.msg )					alert(res.msg);									} catch(e) {				alert('예외가 발생했습니다\n' + e);			}		}			});	   <?php if( $R['uid'] && $R['upload'] ):?>   $('#ck-upload-list').show();   <?php endif?>	}); //document ready//첨부파일 삭제function deleteUpload(tg,upid) {	if( confirm('이 첨부파일을 삭제하시겠습니까?') == false )		return;	//$('#' + upid+'-photo-box').remove();	$('#' + upid + ' a').remove();	$('#' + upid).append('<span style="float:right"> <img src="'+rooturl+'/modules/news/themes/_pc/default/image/ajax-loader.gif"> </span>');		$('#'+tg+' [name="upid"]').val(upid);	$('#'+tg).submit();}function getFilesizeStr(bytes) {	var exp = Math.log(bytes) / Math.log(1024) | 0;	var result = (bytes / Math.pow(1024, exp)).toFixed(2);	return result + ' ' + (exp == 0 ? 'bytes': 'KMGTPEZY'[exp - 1] + 'B');}//파일 바이트 체크 221112class CKUploadAdapter {    constructor( loader ) {        // The file loader instance to use during the upload.        this.loader = loader;    }    // Starts the upload process.    upload() {        return this.loader.file            .then( file => new Promise( ( resolve, reject ) => {                this._initRequest();                this._initListeners( resolve, reject, file );                this._sendRequest( file );            } ) );    }    // Aborts the upload process.    abort() {        if ( this.xhr ) {            this.xhr.abort();        }    }	    // Initializes the XMLHttpRequest object using the URL passed to the constructor.    _initRequest() {        const xhr = this.xhr = new XMLHttpRequest();        // Note that your request may look different. It is up to you and your editor        // integration to choose the right communication channel. This example uses        // a POST request with JSON as a data structure but your configuration        // could be different.        //xhr.open( 'POST', g5_url+'/plugin/editor/'+g5_editor+'/imageUpload/upload.php', true );		//xhr.open( 'POST', rooturl+'/?r='+raccount+'&m=config&a=menu_upload_ck', true );		xhr.open( 'POST', '<?php echo $d_img_domain?>/upload/a.news_photo_upload_ck.php', true );        xhr.responseType = 'json';				//폴더 넘김 하단에 정의 240724        //const data = {	        //folder: "<?php echo $folder?>",        //};        //xhr.send(JSON.stringify(data)); //JSON.stringify를 통해 오브젝트 데이터를 문자열 형태로 변경해서 전송해야 함.				    }    // Initializes XMLHttpRequest listeners.    _initListeners( resolve, reject, file ) {        const xhr = this.xhr;        const loader = this.loader;        const genericErrorText = `Couldn't upload file: ${ file.name }.`;        xhr.addEventListener( 'error', () => reject( genericErrorText ) );        xhr.addEventListener( 'abort', () => reject() );        xhr.addEventListener( 'load', () => {            const response = xhr.response;			if(response.code>0) {								//console.log(JSON.stringify(response));									   // 데이타 불러옴                       $.ajax({                          url: rooturl+"/modules/news/action/a.news_photo_upload_db.php",                          data: {                             "account" : raccount,                             "site" : <?php echo $s?>,						                             "mbruid" : <?php echo $my['uid']?>,                             "save_code" : $("#save-code").val(),                             "up_hidden": response.hidden,							                             "up_folder": response.folder,						                             "up_type": response.type,                             "up_fileExt": response.ext,						                             "up_name": response.name,                             "up_tmpname": response.tmpname,                             "up_thumbname": response.thumbname,                             "up_size": response.size,                             "up_width": response.width,                             "up_height": response.height                          },                          type: "POST",                          success: function(data){                             if (data) {						     //console.log(JSON.stringify(data));						     var upid = data;			//이미지 첨부 221112			var upt = $("#upfilesValue").val(); //업로드 파일이 있는지 확인 1번째인지 여부			document.getElementById('upfilesValue').value = document.getElementById('upfilesValue').value + '[' +upid + ']';			var remove = '<div class="listbox"><span class="name photo-gallery" id="'+ response.url +'^'+ response.width +'">'+ response.name + ' (' + getFilesizeStr(response.size) + ')</span>';			       remove += '<div class="txt">';				   if(!upt) { //처음 등록한 이미지 이면				   remove += '<div class="first-img tooltip_event" title="대표이미지 선택"><input type="radio" id="first-'+ upid +'" name="first_img" value="'+ upid +'" checked="checked"> <label for="first-'+ upid +'" style="position:relative;top:2px;"> <span></span> </label></div>';				   }else{				   remove += '<div class="first-img tooltip_event" title="대표이미지 선택"><input type="radio" id="first-'+ upid +'" name="first_img" value="'+ upid +'"> <label for="first-'+ upid +'" style="position:relative;top:2px;"> <span></span> </label></div>';				   }				   remove += '<span class="delete"><a href="javascript:deleteUpload(\'deleteForm\',' + upid + ')"><span class="badge bg-secondary tooltip_event" title="이 파일을 삭제합니다"><i class="fa fa-trash"></i></span></a></span>';				   remove += '</div></div>';									$('#ck-upload-list ul').append('<li id="' + upid + '" class="list-group-item">' +remove+ '</li>');		            $('#ck-upload-list').show();					//$('').append('.ck-content { min-height: ' + $('textarea[name="content"]').height() + 'px !important; }');					//<figure class="image image-style-align-left">			//이미지 첨부 221112 			                             }                         }                      });			         // 데이타 불러옴						}            // This example assumes the XHR server's "response" object will come with            // an "error" which has its own "message" that can be passed to reject()            // in the upload promise.            //            // Your integration may handle upload errors in a different way so make sure            // it is done properly. The reject() function must be called when the upload fails.            if ( !response || response.error ) {                return reject( response && response.error ? response.error.message : genericErrorText );            }            // If the upload is successful, resolve the upload promise with an object containing            // at least the "default" URL, pointing to the image on the server.            // This URL will be used to display the image in the content. Learn more in the            // UploadAdapter#upload documentation.            resolve( {                default: response.url            } );        } );        // Upload progress when it is supported. The file loader has the #uploadTotal and #uploaded        // properties which are used e.g. to display the upload progress bar in the editor        // user interface.        if ( xhr.upload ) {            xhr.upload.addEventListener( 'progress', evt => {                if ( evt.lengthComputable ) {					editor.execute( 'imageStyle', { value: '<?php echo $img_align?>' } ); //***** 업로드 이미지를 기본 좌측정렬                    loader.uploadTotal = evt.total;                    loader.uploaded = evt.loaded;                }            } );        }    }    // Prepares the data and sends the request.    _sendRequest( file ) {        // Prepare the form data.        const data = new FormData();        data.append( 'file', file );		data.append( 'folder', '<?php echo $folder?>'); //240724        // Important note: This is the right place to implement security mechanisms        // like authentication and CSRF protection. For instance, you can use        // XMLHttpRequest.setRequestHeader() to set the request headers containing        // the CSRF token generated earlier by your application.        // Send the request.        this.xhr.send( data );    }}function CKEditorUploadAdapterPlugin( editor ) {    editor.plugins.get( 'FileRepository' ).createUploadAdapter = ( loader ) => {        // Configure the URL to the upload script in your back-end here!        return new CKUploadAdapter( loader );    };}//본문에 내용추가function intTEXT( editor ) {editor.model.change( writer => {    const insertPosition = editor.model.document.selection.getFirstPosition();    writer.insertText( 'foo', { bold: true }, insertPosition );} );}const customColorPalette = [    {        color: 'hsl(39, 0%, 100%)',        label: 'White'    },    {        color: 'hsl(4, 